'use strict';

/* Experiência essencial inspirada na planilha original. Os dados avançados
   continuam preservados e acessíveis em “Mais”. */
if(!Array.isArray(db.fundYields))db.fundYields=[];
if(!Array.isArray(db.fundSnapshots))db.fundSnapshots=[];
if(!db.paymentHistoryMonthByTrip)db.paymentHistoryMonthByTrip={};
if(!Array.isArray(db.shoppingItems))db.shoppingItems=[];
if(!Array.isArray(db.consumptionGroups))db.consumptionGroups=[];
if(!db.shoppingImports)db.shoppingImports={};
if(!db.simplePage)db.simplePage='inicio';
const SIMPLE_NAV=[['inicio','⌂','Visão geral'],['contribuicoes','$','Contribuições'],['gastos','▤','Gastos'],['compras','☷','Compras'],['pessoas','♙','Pessoas'],['mais','•••','Mais']];
let simpleMapPointer=null,simpleMapMoved=false;
const tripYields=()=>(db.fundYields||=[]).filter(item=>item.trip===db.active);
const tripFundSnapshots=()=>(db.fundSnapshots||=[]).filter(item=>item.trip===db.active);
const latestFundSnapshot=()=>tripFundSnapshots().slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||'').localeCompare(a.createdAt||''))[0];
const tripShopping=()=>(db.shoppingItems||=[]).filter(item=>item.trip===db.active);
const tripConsumptionGroups=()=>(db.consumptionGroups||=[]).filter(item=>item.trip===db.active);
const yieldTotal=()=>latestFundSnapshot()?.netYieldCents??tripYields().reduce((sum,item)=>sum+item.amountCents,0);
const currentShoppingYear=()=>Number(db.shoppingYear)||shoppingYears()[0]||new Date().getFullYear();
const shoppingTotal=()=>tripShopping().filter(item=>item.year===currentShoppingYear()&&item.purchased!==false).reduce((sum,item)=>sum+(item.actualTotalCents??(item.quantity||0)*(item.unitPriceCents||0)),0);
const hasMarketTotal=()=>expenses().some(item=>item.category==='mercado'&&(item.paidCents||item.plannedCents));
const appliedShoppingTotal=()=>hasMarketTotal()?0:shoppingTotal();
const simpleOut=()=>spent()+appliedShoppingTotal();
const openingBalance=()=>Number(trip()?.contributionPlan?.openingBalanceCents)||0;
const balanceBeforeYield=()=>openingBalance()+received()-simpleOut();
const simpleBalance=()=>openingBalance()+received()+yieldTotal()-simpleOut();
const planMonths=()=>trip()?.contributionPlan?.months||[];
const planPeople=()=>{const plan=trip()?.contributionPlan||{},ids=plan.participantIds||[],order=plan.participantOrder||ids;return people().filter(person=>person.contributes!==false&&(!ids.length||ids.includes(person.id))).sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?9999:ai)-(bi<0?9999:bi)})};
const plannedPeopleCount=()=>Math.max(0,Number(trip()?.contributionPlan?.peopleCount)||planPeople().length);
const plannedPayerCount=()=>Math.max(0,Number(trip()?.contributionPlan?.payerCount)||planPeople().filter(person=>person.contributes!==false).length);
const expectedContributions=()=>{const plan=trip()?.contributionPlan;if(!plan)return 0;if(plan.mode==='cost_split')return Math.max(0,(Number(plan.goalCents)||0)-openingBalance());return plannedPayerCount()*(Number(plan.monthlyCents)||0)*planMonths().length};
const projectedFund=()=>trip()?.contributionPlan?.mode==='cost_split'?Number(trip().contributionPlan.goalCents)||0:openingBalance()+expectedContributions();
const monthName=value=>value?new Intl.DateTimeFormat('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}).format(new Date(value+'-15T12:00:00Z')).replace('.',''):'—';
const allTripPeople=()=>own(db.people);
function syncSimplePeoplePlan(){const plan=trip()?.contributionPlan;if(!plan)return;const active=people(),payers=active.filter(person=>person.contributes!==false),payerIds=new Set(payers.map(person=>person.id));plan.peopleCount=active.length;plan.payerCount=payers.length;plan.participantIds=(plan.participantIds||[]).filter(id=>payerIds.has(id));payers.forEach(person=>{if(!plan.participantIds.includes(person.id))plan.participantIds.push(person.id)});plan.participantOrder=(plan.participantOrder||[]).filter(id=>payerIds.has(id));plan.participantIds.forEach(id=>{if(!plan.participantOrder.includes(id))plan.participantOrder.push(id)});if(plan.mode==='cost_split'&&plan.goalCents&&payers.length)plan.monthlyCents=Math.ceil(Math.max(0,plan.goalCents-(plan.openingBalanceCents||0))/(payers.length*Math.max(1,plan.monthCount||1)));trip().guests=active.length;trip().payers=payers.length}
const simplePreviousAddMembers=addMembersToTrip;
addMembersToTrip=function(memberIds){let restored=0;memberIds.forEach(memberId=>{const person=allTripPeople().find(item=>item.memberId===memberId&&item.removedFromTrip===true);if(person){person.removedFromTrip=false;delete person.removedAt;restored++}});const added=simplePreviousAddMembers(memberIds);if(added||restored)syncSimplePeoplePlan();return added+restored};
function simpleShell(title,subtitle,action='',body=''){return head(title,subtitle,action)+body}
function needTrip(){return simpleShell('Organize sua primeira viagem','Crie uma viagem e escolha como o grupo vai formar a caixinha.','<button class="button primary" data-new-trip>+ Nova viagem</button>',empty('◇','Nenhuma viagem','Uma viagem começa apenas com nome, pessoas e a forma de contribuição.'))}
function organizationLabel(){return trip()?.contributionPlan?.mode==='cost_split'?'Dividir um valor definido':'Juntar dinheiro primeiro'}

function simpleHome(){
  if(!trip())return needTrip();const expected=expectedContributions(),projected=projectedFund(),got=received(),returns=yieldTotal(),out=simpleOut(),balance=simpleBalance(),pending=Math.max(0,expected-got),pct=expected?Math.min(100,Math.round(got/expected*100)):0;
  const setup=!trip().contributionPlan?`<section class="simple-choice"><div><p class="eyebrow">COMECE POR AQUI</p><h2>Como o grupo quer organizar esta viagem?</h2><p>Essa escolha pode ser alterada depois.</p></div><div class="simple-choice-grid"><button data-start-mode="fund_first"><b>Juntar dinheiro primeiro</b><span>Cada pessoa contribui mensalmente e vocês procuram uma casa depois.</span></button><button data-start-mode="cost_split"><b>Dividir o custo da viagem</b><span>Informe o valor pretendido e divida entre pessoas e meses.</span></button></div></section>`:'';
  const surplus=balance>0?`<section class="card surplus-card"><div><h2>Destino da sobra</h2><p>O saldo da caixinha pode ficar para a próxima viagem ou ser dividido igualmente.</p></div><div class="quick-segments"><button class="${trip().surplusPolicy==='carry'?'selected':''}" data-surplus="carry">Guardar</button><button class="${trip().surplusPolicy==='split'?'selected':''}" data-surplus="split">Dividir</button><button class="${!trip().surplusPolicy||trip().surplusPolicy==='undecided'?'selected':''}" data-surplus="undecided">Decidir depois</button></div>${trip().surplusPolicy==='split'&&people().length?`<strong>${cash(Math.floor(balance/people().length))} por pessoa</strong>`:''}</section>`:'';
  return simpleShell(trip().name,`${esc(trip().region||'Destino ainda não escolhido')} · ${organizationLabel()}`,'<button class="button primary" data-new-trip>+ Nova viagem</button>',setup+`<div class="simple-metrics">${metric('Previsão final',cash(projected),`${plannedPayerCount()} pagantes · ${planMonths().length} meses`)}${metric('Viajantes',plannedPeopleCount(),`${plannedPayerCount()} contribuem`)}${metric('Saldo inicial',cash(openingBalance()),'Valor que já estava arrecadado')}${metric('Contribuído',cash(got),'Pagamentos registrados')}${metric('Rendimentos',cash(returns),'Ajustes da caixinha')}${metric('Disponível',cash(balance),'Saldo inicial + entradas − gastos')}</div><section class="card cash-progress"><div class="section-head"><div><h2>Caixinha da viagem</h2><p>${pct}% das contribuições previstas foram recebidas</p></div><strong>${cash(pending)} faltando</strong></div><div class="progress"><span style="width:${pct}%"></span></div><div class="simple-actions"><button class="button primary" data-simple-page="contribuicoes">Registrar contribuição</button><button class="button secondary" data-simple-page="gastos">Adicionar gasto</button><button class="button secondary" data-simple-page="compras">Abrir compras</button></div></section>${surplus}`);
}

function contributionSetup(){
  const plan=trip()?.contributionPlan||{},mode=plan.mode||'fund_first',members=people();
  const count=plan.peopleCount||Math.max(members.length,1),payerCount=plan.payerCount||Math.max(members.filter(person=>person.contributes!==false).length,1),opening=plan.openingBalanceCents||0,preview=mode==='cost_split'?(plan.goalCents||0):opening+(plan.monthlyCents||0)*payerCount*(plan.monthCount||12);
  const configured=Boolean(plan.months?.length);
  return `<details class="config-details card" ${configured?'':'open'}><summary><div><b>Configuração da caixinha</b><span>${payerCount} pagantes · ${cash(plan.monthlyCents||0)}/mês · ${plan.monthCount||12} meses</span></div><strong>${cash(preview)}</strong></summary><form id="simple-plan"><div class="section-head"><div><h2>Como formar a caixinha</h2><p>Depois de configurada, esta área fica recolhida.</p></div></div><div class="mode-cards simple-modes"><label class="mode-card"><input type="radio" name="mode" value="fund_first" ${mode==='fund_first'?'checked':''}><span><b>Juntar primeiro</b><small>Valor por pagante durante alguns meses.</small></span></label><label class="mode-card"><input type="radio" name="mode" value="cost_split" ${mode==='cost_split'?'checked':''}><span><b>Dividir um valor</b><small>Casa e outros custos divididos somente pelos pagantes.</small></span></label></div><div class="form-grid">${field('planPeopleCount','Quantidade total de pessoas','number',count,'required min="1" max="500" step="1"')}${field('planPayerCount','Quantas pessoas vão pagar?','number',Math.min(count,payerCount),'required min="1" max="500" step="1"')}${field('planMonthly','Valor mensal por pagante (R$)','number',inputMoney(plan.monthlyCents||0),'min="0" step="0.01"')}${field('planCount','Quantidade de meses','number',plan.monthCount||12,'min="1" max="36" step="1" required')}${field('planOpening','Já existe dinheiro arrecadado? (R$)','number',inputMoney(opening),'min="0" step="0.01"')}${field('planStart','Primeiro mês','month',plan.startMonth||today().slice(0,7),'required')}${field('planGoal','Orçamento / valor total da viagem (R$)','number',inputMoney(plan.goalCents||trip().totalBudgetCents||0),'min="0" step="0.01"')}</div><div class="plan-live" data-plan-preview><span>Previsão final da caixinha</span><strong>${cash(preview)}</strong><small>${payerCount} pagantes × ${plan.monthCount||12} meses, mais o saldo inicial · ${count} viajantes</small></div>${members.length?`<div class="field"><label>Configure quem aparece na planilha de contribuições</label><div class="payer-config-grid">${members.map(person=>`<article class="payer-config"><label><input type="checkbox" name="planParticipant" value="${person.id}" ${person.contributes!==false&&(!(plan.participantIds||[]).length||(plan.participantIds||[]).includes(person.id))?'checked':''}><span><b>${esc(person.name)}</b><small>${person.participantType==='child'?'Criança':'Adulto'} · ${person.contributes===false?'Não pagante':'Pagante'}</small></span></label><button type="button" class="button ghost small" data-edit-person-v3="${person.id}">Editar</button></article>`).join('')}</div><p class="help">Somente pessoas marcadas como pagantes aparecerão na grade mensal.</p></div>`:'<div class="notice info">Depois de salvar, a tela “Pessoas” mostrará os espaços para preencher os nomes e indicar quem paga.</div>'}<div class="actions"><button class="button primary">Salvar planejamento simples</button></div></form></details>`;
}
function monthlyGrid(){
  const months=planMonths(),members=planPeople();if(!months.length||!members.length)return empty('▦','Planejamento incompleto','Defina pessoas, valor e meses acima.');
  const current=today().slice(0,7),rows=members.map(person=>{const values=months.map(month=>allocations().filter(item=>item.participantId===person.id&&item.referenceMonth===month).reduce((sum,item)=>sum+item.amountCents,0));return `<tr draggable="true" data-payer-row="${person.id}"><td><div class="payer-cell"><span class="drag-handle" title="Arrastar para ordenar">⋮⋮</span><button type="button" class="payer-name-button" data-edit-person-v3="${person.id}" title="Editar cadastro de ${esc(person.name)}">${esc(person.name)}</button><button type="button" class="person-report-button" data-person-report="${person.id}" title="Ver relatório de contribuições">Relatório</button></div></td>${months.map((month,index)=>`<td class="payment-cell ${values[index]?'paid':''} ${month===current?'current':''}"><button class="month-payment" ${!values[index]&&month===current?`data-confirm-month="${person.id}|${month}"`:`data-simple-payment="${person.id}|${month}"`}>${values[index]?cash(values[index]):month===current?'Confirmar':'+'}</button></td>`).join('')}<td><strong>${cash(values.reduce((a,b)=>a+b,0))}</strong></td></tr>`}).join('');
  return `<section class="card"><div class="section-head"><div><h2>Contribuições por mês</h2><p>No mês vigente, basta tocar em “Confirmar”. Qualquer célula pode ser editada depois.</p></div><button class="button primary small" data-group-payment>+ Pagamento para várias pessoas</button></div><div class="table-wrap"><table class="finance-table simple-table"><thead><tr><th>Pessoa</th>${months.map(month=>`<th class="${month===current?'current-month':''}">${monthName(month)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
}
function fundBalancePanel(){const snapshot=latestFundSnapshot(),base=balanceBeforeYield(),gross=snapshot?.grossBalanceCents,net=snapshot?.netBalanceCents,grossYield=snapshot?.grossYieldCents,netYield=snapshot?.netYieldCents,deductions=snapshot?Math.max(0,gross-net):0;return `<section class="card fund-balance-panel"><div class="section-head"><div><h2>Saldo e rendimento da caixinha</h2><p>Informe o saldo atual da conta; o rendimento é calculado automaticamente.</p></div>${snapshot?`<span class="balance-updated">Atualizado em ${date(snapshot.date)}</span>`:''}</div><div class="fund-balance-metrics">${metric('Saldo sem rendimento',cash(base),'Saldo inicial + arrecadado − gastos')}${metric('Saldo bruto',snapshot?cash(gross):'—',snapshot?`Rendimento bruto ${cash(grossYield)}`:'Antes de impostos e taxas')}${metric('Saldo líquido',snapshot?cash(net):cash(base),'Valor realmente disponível')}${metric('Rendimento líquido',snapshot?cash(netYield):cash(yieldTotal()),snapshot&&deductions?`${cash(deductions)} em impostos/taxas`:'Diferença encontrada')}</div><form id="simple-balance" class="fund-balance-form">${field('balanceDate','Data da conferência','date',today(),'required')}${field('balanceGross','Saldo bruto da conta (R$)','number',snapshot?inputMoney(gross):'','min="0" step="0.01" placeholder="Opcional"')}${field('balanceNet','Saldo líquido disponível (R$)','number',snapshot?inputMoney(net):'','min="0" step="0.01" placeholder="Opcional"')}${field('balanceNote','Observação','text',snapshot?.note||'','maxlength="100" placeholder="Ex.: saldo mostrado na caixinha"')}<button class="button secondary">Atualizar saldo</button></form><p class="help">Preencha apenas um dos saldos se sua conta não mostrar bruto e líquido separadamente.</p></section>`}
function simplePaymentHistory(){const available=[...new Set([...planMonths(),...pays().map(payment=>payment.referenceMonth).filter(Boolean)])].sort(),saved=db.paymentHistoryMonthByTrip[db.active],selected=saved==='all'||available.includes(saved)?saved:(available.includes(today().slice(0,7))?today().slice(0,7):available.at(-1)||'all'),filtered=selected==='all'?pays():pays().filter(payment=>payment.referenceMonth===selected),rows=filtered.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(payment=>{const valid=payment.allocations||[],names=valid.map(item=>allTripPeople().find(person=>person.id===item.participantId)?.name||item.participantName).filter(Boolean),allocated=valid.reduce((sum,item)=>sum+item.amountCents,0),issue=!names.length||allocated!==payment.amountCents,monthly=payment.source?.type==='simple-monthly'&&valid.length===1&&people().some(person=>person.id===valid[0].participantId),edit=payment.source?.type==='simple-group'?`<button class="button ghost small" data-edit-group-payment="${payment.id}">Editar</button>`:monthly?`<button class="button ghost small" data-simple-payment="${valid[0].participantId}|${payment.referenceMonth}">Editar</button>`:'';return `<div class="record"><div><strong>${names.length?esc(names.join(', ')):'Pagamento a revisar'}</strong><div class="record-meta">${date(payment.date)} · ${monthName(payment.referenceMonth)} · registrado por ${esc(payment.payer||'não informado')}${issue?' · valores precisam de revisão':''}</div></div><div class="record-side"><strong>${cash(payment.amountCents)}</strong><div class="record-actions">${edit}<button class="button danger small" data-cancel-contribution-payment="${payment.id}">Cancelar</button></div></div></div>`}).join('')||'<p class="help">Nenhum pagamento registrado neste mês.</p>';return `<section class="card"><div class="section-head payment-history-head"><div><h2>Pagamentos registrados</h2><p>${filtered.length} registro${filtered.length===1?'':'s'} no período selecionado.</p></div><label><span>Filtrar por mês</span><select data-payment-month-filter><option value="all" ${selected==='all'?'selected':''}>Todos os meses</option>${available.map(month=>`<option value="${month}" ${selected===month?'selected':''}>${monthName(month)}</option>`).join('')}</select></label></div>${rows}</section>`}
function simpleContributions(){if(!trip())return needTrip();return simpleShell('Contribuições','Pessoas, meses, saldo e rendimentos em uma visão parecida com sua planilha.', '',`<div class="simple-stack">${contributionSetup()}${fundBalancePanel()}${monthlyGrid()}${simplePaymentHistory()}</div>`)}

function simpleExpenses(){
  if(!trip())return needTrip();const pending=expenses().reduce((sum,item)=>sum+Math.max(0,item.plannedCents-item.paidCents),0),rows=expenses().slice().sort((a,b)=>(a.paidCents>=a.plannedCents)-(b.paidCents>=b.plannedCents)||(a.date||'9999').localeCompare(b.date||'9999')).map(item=>{const left=Math.max(0,item.plannedCents-item.paidCents),paid=item.status==='pago'||left===0;return `<article class="expense-row ${paid?'is-paid':''}"><div class="expense-main"><div class="expense-title"><strong>${esc(item.description)}</strong><span class="expense-status ${paid?'paid':item.paidCents?'partial':'planned'}">${paid?'Pago':item.paidCents?'Parcial':'Previsto'}</span></div><small>${esc(item.category)} · ${item.date?`Vencimento ${date(item.date)}`:'Sem vencimento'}${item.paidAt?` · último pagamento ${date(item.paidAt)}`:''}</small></div><div class="expense-value"><small>Previsto</small><strong>${cash(item.plannedCents)}</strong></div><div class="expense-value"><small>Realizado</small><strong>${cash(item.paidCents)}</strong></div><div class="expense-value"><small>${paid?'Quitado':'Falta'}</small><strong>${cash(left)}</strong></div><div class="expense-row-actions">${!paid?`<button class="button primary small" data-pay-expense="${item.id}">Confirmar pagamento</button>`:''}<button class="button ghost small" data-edit-simple-expense="${item.id}">Editar gasto</button>${item.paidCents>0?`<button class="button ghost small" data-manage-expense-payments="${item.id}">Editar pagamentos</button>`:''}${paid?'<span class="expense-paid-check">✓</span>':''}</div></article>`}).join('')||empty('▤','Nenhum gasto','Use “Adicionar gasto” para criar o primeiro lançamento.');
  return simpleShell('Gastos','Financeiro simples: acompanhe o previsto, o realizado e os próximos pagamentos.','<button class="button primary" data-add-simple-expense>+ Adicionar gasto</button>',`<div class="simple-metrics">${metric('Previsto',cash(planned()),'Total dos compromissos')}${metric('Realizado',cash(spent()),'Pagamentos confirmados')}${metric('A pagar',cash(pending),'Valores ainda pendentes')}${metric('Saldo disponível',cash(simpleBalance()),'Depois do que já foi pago')}</div><section class="card expense-ledger"><div class="section-head"><div><h2>Gastos da viagem</h2><p>Itens pendentes aparecem primeiro. Confirme o pagamento diretamente na lista.</p></div><span class="expense-count">${expenses().length} lançamento${expenses().length===1?'':'s'}</span></div><div class="expense-list">${rows}</div></section><div class="notice info" style="margin-top:16px">Mercado pode ser lançado como um total aqui ou discriminado na lista de compras. Quando houver um total de mercado, a lista detalhada não será descontada novamente.</div>`)}
function simpleExpenseModal(){modal('Adicionar gasto','Cadastre à vista, parcelado ou com datas combinadas.',`<form id="simple-expense"><div class="stack">${field('expenseDescription','Descrição','text','','required maxlength="100" placeholder="Ex.: Casa em Teresópolis"')}${select('expenseCategory','Categoria',CATS.map(value=>[value,value[0].toUpperCase()+value.slice(1)]),'aluguel')}${field('expensePlanned','Valor total previsto (R$)','number','','required min="0.01" step="0.01"')}${select('expenseSchedule','Forma de pagamento',[['single','Pagamento único'],['monthly','Parcelado mensalmente'],['dates','Datas definidas pelo locatário']],'single')}<div class="form-grid">${field('expenseInstallments','Quantidade de parcelas','number','1','min="1" max="60" step="1"')}${field('expenseDate','Primeira data / data única','date',today())}</div><div class="field"><label for="expenseSpecificDates">Datas específicas</label><textarea id="expenseSpecificDates" name="expenseSpecificDates" placeholder="Uma data por linha, no formato AAAA-MM-DD"></textarea><p class="help">Use quando os vencimentos não forem mensais.</p></div><div class="actions"><button type="button" class="button ghost" data-close>Cancelar</button><button class="button secondary" data-expense-action="save">Apenas adicionar</button><button class="button primary" data-expense-action="pay">Adicionar e pagar agora</button></div></div></form>`)}
function simpleExpensePaymentModal(expenseId){const item=db.expenses.find(value=>value.id===expenseId&&value.trip===db.active);if(!item)return toast('Gasto não encontrado.','error');const pending=Math.max(0,item.plannedCents-item.paidCents);modal('Confirmar pagamento',esc(item.description),`<form id="simple-expense-payment" data-id="${item.id}"><div class="expense-payment-summary"><span>Previsto <b>${cash(item.plannedCents)}</b></span><span>Já realizado <b>${cash(item.paidCents)}</b></span><span>Falta <b>${cash(pending)}</b></span></div>${field('expensePaymentAmount','Valor pago agora (R$)','number',inputMoney(pending),'required min="0.01" max="'+inputMoney(pending)+'" step="0.01"')}${field('expensePaymentDate','Data do pagamento','date',today(),'required')}<div class="actions"><button type="button" class="button ghost" data-close>Cancelar</button><button class="button primary">Confirmar pagamento</button></div></form>`)}
function editSimpleExpenseModal(expenseId){const item=db.expenses.find(value=>value.id===expenseId&&value.trip===db.active);if(!item)return toast('Gasto não encontrado.','error');modal('Editar gasto','Também é possível corrigir lançamentos ainda não pagos.',`<form id="simple-expense-item-edit" data-id="${item.id}"><div class="stack">${field('expenseItemDescription','Descrição','text',item.description,'required maxlength="100"')}${select('expenseItemCategory','Categoria',CATS.map(value=>[value,value[0].toUpperCase()+value.slice(1)]),item.category)}${field('expenseItemPlanned','Valor previsto (R$)','number',inputMoney(item.plannedCents),'required min="'+inputMoney(item.paidCents)+'" step="0.01"')}${field('expenseItemDate','Vencimento','date',item.date||'')}<div class="actions"><button type="button" class="button ghost" data-close>Cancelar</button><button class="button primary">Salvar alterações</button></div></div></form>`)}
function normalizeExpensePayments(item){if(!Array.isArray(item.expensePayments))item.expensePayments=[];const recorded=item.expensePayments.reduce((sum,payment)=>sum+(Number(payment.amountCents)||0),0),difference=Math.max(0,(Number(item.paidCents)||0)-recorded);if(difference)item.expensePayments.unshift({id:uid(),amountCents:difference,date:item.paidAt||item.date||today(),legacy:true});return item.expensePayments}
function syncExpensePayments(item){if(!Array.isArray(item.expensePayments))item.expensePayments=[];item.paidCents=item.expensePayments.reduce((sum,payment)=>sum+(Number(payment.amountCents)||0),0);item.status=item.paidCents>=item.plannedCents?'pago':item.paidCents>0?'parcial':'previsto';item.paidAt=item.expensePayments.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]?.date||''}
function manageExpensePaymentsModal(expenseId){const item=db.expenses.find(value=>value.id===expenseId&&value.trip===db.active);if(!item)return toast('Gasto não encontrado.','error');const payments=normalizeExpensePayments(item),rows=payments.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(payment=>`<div class="expense-payment-record"><div><strong>${cash(payment.amountCents)}</strong><small>${date(payment.date)}</small></div><div><button type="button" class="button ghost small" data-edit-expense-payment="${item.id}|${payment.id}">Editar</button><button type="button" class="button danger small" data-cancel-expense-payment="${item.id}|${payment.id}">Cancelar pagamento</button></div></div>`).join('')||'<p class="help">Nenhum pagamento registrado.</p>';modal('Pagamentos registrados',esc(item.description),`<div class="expense-payment-summary"><span>Previsto <b>${cash(item.plannedCents)}</b></span><span>Realizado <b>${cash(item.paidCents)}</b></span><span>Falta <b>${cash(Math.max(0,item.plannedCents-item.paidCents))}</b></span></div><div class="expense-payment-records">${rows}</div><div class="actions"><button type="button" class="button secondary" data-close>Fechar</button></div>`)}
function editExpensePaymentModal(expenseId,paymentId){const item=db.expenses.find(value=>value.id===expenseId&&value.trip===db.active);if(!item)return;const payment=normalizeExpensePayments(item).find(value=>value.id===paymentId);if(!payment)return toast('Pagamento não encontrado.','error');const others=item.expensePayments.filter(value=>value.id!==paymentId).reduce((sum,value)=>sum+value.amountCents,0),maximum=Math.max(0,item.plannedCents-others);modal('Editar pagamento',esc(item.description),`<form id="simple-expense-payment-edit" data-expense="${item.id}" data-payment="${payment.id}">${field('expenseEditAmount','Valor (R$)','number',inputMoney(payment.amountCents),'required min="0.01" max="'+inputMoney(maximum)+'" step="0.01"')}${field('expenseEditDate','Data do pagamento','date',payment.date||today(),'required')}<div class="actions"><button type="button" class="button ghost" data-manage-expense-payments="${item.id}">Voltar</button><button class="button primary">Salvar alteração</button></div></form>`)}

